/// <summary>
/// Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
/// </summary>
[ExtensionOf(classStr(TAMRebateQueryBuilder))]
final class METTAMRebateQueryBuilder_Extension
{
    private RecId journalRecId;
    private RecId lineRecId;

    // Variable to identify if provision or rebate
    private TAMRebateTransactionType metRebateTransactionType;
}

Method.Source:
/// <summary>
/// Parm method for the rebate transaction type
/// </summary>
/// <param name = "_metRebateTransactionType"><c>TAMRebateTransactionType</c></param>
/// <returns><c>TAMRebateTransactionType</c></returns>
public TAMRebateTransactionType metParmRebateTransactionType(TAMRebateTransactionType _metRebateTransactionType = metRebateTransactionType)
{
    metRebateTransactionType = _metRebateTransactionType;
    return metRebateTransactionType;
}

/// <summary>
/// Filter transactions by the deal custom vendor account
/// Adding the vendor account range
/// </summary>
void metAddVendAccountRange()
{
    // When using line attributes for vendor rebates AccountCode will be set to All
    if (rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend
    &&  rebateTable.AccountCode          == TableGroupAll::All)
    {
        VendAccount vendAccount = rebateTable.TAMRebateDeal().METVendAccount;

        if (vendAccount)
        {
            // Force the filtering, we are only using line attributes (products) and not header attributes (vendor)
            SysQuery::findOrCreateRange(query.dataSourceTable(this.journalTable()), this.accountJourTableFieldId()).value(vendAccount);
        }
    }
}

/// <summary>
/// Adding the range for the external sales data processed flags based on the transaction types
/// </summary>
void metAddExternalSalesDataRange()
{
    if (metRebateTransactionType == TAMRebateTransactionType::Provision)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, ProvisionProcessed)).value(queryValue(NoYes::No));
    }
    else if (metRebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, RebateProcessed)).value(queryValue(NoYes::No));
    }
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Adding the item distribution method filters
/// Ideally this should only be added in TAMRebateQueryBuilderSalesOrder, TAMRebateQueryBuilderSalesDeliveryNote and TAMRebateQueryBuilderSalesInvoice
/// but TAMRebateQueryBuilderSalesDeliveryNote and TAMRebateQueryBuilderSalesInvoice are internal
/// </summary>
/// <returns>Updated <c>Query</c> object</returns>
public Query buildCalculateAmountQuery()
{
    query = next buildCalculateAmountQuery();

    // For aggregated rebates, it is important that the sorting of the transactions in the query.
    // For example, all the transaction must be sorted by Account number if it is aggregated by Account. This is to ensure that when processing the transactions, all transactions for an account are processed together.
    query.dataSourceTable(this.journalTable()).addOrderByField(this.accountJourTableFieldId(), SortOrder::Ascending);

    // Add the item distribution method filter
    this.metAddItemDistributionMethodRange();

    if(query.dataSourceTable(this.journalTable()) && query.dataSourceTable(this.journalTable()).findRange(fieldNum(Common, RecId)))
    {
        journalRecId = any2Int64(query.dataSourceTable(this.journalTable()).findRange(fieldNum(Common, RecId)).value());
    }
    if(query.dataSourceTable(this.transTable()) && query.dataSourceTable(this.transTable()).findRange(fieldNum(Common, RecId)))
    {
        lineRecId = any2Int64(query.dataSourceTable(this.transTable()).findRange(fieldNum(Common, RecId)).value());
    }

    // Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
    // Handle OR attributes if any
    METTAMRebateQueryBuilderORAttributesFacade facade = METTAMRebateQueryBuilderORAttributesFacade::construct(this, rebateTable, query);
    query = facade.run();        

    return query;
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Copied the private method to add inventory dimension data source if it doesn't exist
/// </summary>
protected void metAddInventDimDS()
{
    // could be already added by standard code if users configured the inventory dimension criteria against TAMRebateTable
    QueryBuildDataSource qdbsInventDim = query.dataSourceTable(tableNum(InventDim));

    if (!qdbsInventDim)
    {      
        QueryBuildDataSource qbds = query.dataSourceTable(this.transTable()).addDataSource(tableNum(InventDim));

        qbds.relations(true);
        qbds.joinMode(JoinMode::ExistsJoin);
        qbds.fetchMode(QueryFetchMode::One2One);
    }

    //inventDimParm.queryAddRange(qbds, inventDimCriteria);
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Add the default order settings data source
/// </summary>
protected void metAddInventItemOrderSetupDS()
{        
    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(InventDim)).addDataSource(tableNum(METInventItemOrderSetup));

    /*qbds.addLink(this.itemFieldId(), fieldNum(METInventItemOrderSetup, ItemId));*/
    qbds.addLink(fieldNum(InventDim, InventSiteId), fieldNum(METInventItemOrderSetup, SiteId));

    qbds.joinMode(JoinMode::ExistsJoin);
    qbds.fetchMode(QueryFetchMode::One2One);

    QueryBuildRange qbrItemId = SysQuery::findOrCreateRange(qbds, fieldNum(METInventItemOrderSetup, ItemId));

    QueryBuildDataSource qbdsTransTable = query.dataSourceTable(this.transTable());

    const str itemIdRange = '(%1.ITEMID == %2.ITEMID)';

    qbrItemId.value(strFmt(itemIdRange, qbdsTransTable.name(), qbds.name()));
    //inventDimParm.queryAddRange(qbds, inventDimCriteria);
}

/// <summary>
/// Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
/// Filter transactions by the item distribution method
/// </summary>
void metAddItemDistributionMethodRange()
{
    TAMRebateDeal rebateDeal = rebateTable.TAMRebateDeal();

    // Only for customer rebates or vendor rebates based on sales
    // and when item distribution method is selected
    if ((rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
    || (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
    && rebateTable.RebateBasisVend == TAMRebateBasisVend::Sales))
    && rebateTable.METItemDistributionMethod)
    {
        // Add invent dimension ds
        this.metAddInventDimDS();

        // Add default order settings ds
        if (rebateTable.IncludeFreeText != NoYes::Yes)
        {
            this.metAddInventItemOrderSetupDS();
        }

        QueryBuildRange qbr = SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(METInventItemOrderSetup)), fieldNum(METInventItemOrderSetup, DistributionMethod));

        switch (rebateTable.METItemDistributionMethod)
        {
            case METItemDistributionMethod::Warehouse:
                qbr.value(queryValue("W"));
                break;
            case METItemDistributionMethod::ChargeThrough:
                qbr.value(queryValue("H"));
                break;

            default:
                // Do nothing, no filter
                break;
        }
    }
}
